        {
          "id": "header",
          "component": "Text",
          "text": "Family-Friendly Tokyo 5-Day Itinerary: Anime, Tech & Kid Museums",
          "variant": "h1"
        },
        {
          "id": "overview_section",
          "component": "Column",
          "children": [
            "overview_title",
            "overview_text"
          ]
        },
        {
          "id": "overview_title",
          "component": "Text",
          "text": "Overview",
          "variant": "h2"
        },
        {
          "id": "overview_text",
          "component": "Text",
          "text": "This itinerary balances interactive technology experiences, anime-related attractions, and museum visits suitable for 8-10 year olds during early summer (June). The plan assumes moderate walking tolerance for children, access to Tokyo's efficient train system, and pre-booking of popular attractions. Daily costs estimate USD 250-400 per family including meals, transit, and attractions.",
          "variant": "body"
        },
        {
          "id": "context_section",
          "component": "Column",
          "children": [
            "context_title",
            "context_list"
          ]
        },
        {
          "id": "context_title",
          "component": "Text",
          "text": "Context and Assumptions",
          "variant": "h2"
        },
        {
          "id": "context_list",
          "component": "List",
          "direction": "vertical",
          "children": [
            "ctx_1",
            "ctx_2",
            "ctx_3",
            "ctx_4",
            "ctx_5",
            "ctx_6"
          ]
        },
        {
          "id": "ctx_1",
          "component": "Text",
          "text": "• Family staying in a central location (Shinjuku, Shibuya, or Ueno recommended)."
        },
        {
          "id": "ctx_2",
          "component": "Text",
          "text": "• Children comfortable with 2-3 hours of walking daily with rest breaks."
        },
        {
          "id": "ctx_3",
          "component": "Text",
          "text": "• Willingness to book popular attractions 1-2 weeks in advance."
        },
        {
          "id": "ctx_4",
          "component": "Text",
          "text": "• Use of Suica/Pasmo cards for transit efficiency."
        },
        {
          "id": "ctx_5",
          "component": "Text",
          "text": "• Early June weather: warm (75-80°F), possible rain; plan indoor activities accordingly."
        },
        {
          "id": "ctx_6",
          "component": "Text",
          "text": "• Budget includes meals at casual/mid-range restaurants, not fine dining."
        },
