            "d4_morning_title",
            "d4_morning_text",
            "d4_lunch_title",
            "d4_lunch_text",
            "d4_afternoon_title",
            "d4_afternoon_text",
            "d4_evening_title",
            "d4_evening_text",
            "d4_divider",
            "d4_stats"
          ]
        },
        {
          "id": "d4_header",
          "component": "Text",
          "text": "Anime & Gaming District (Akihabara, Shinjuku)",
          "variant": "h3"
        },
        {
          "id": "d4_morning_title",
          "component": "Text",
          "text": "Morning (8:00 AM - 12:00 PM)",
          "variant": "h4"
        },
        {
          "id": "d4_morning_text",
          "component": "Text",
          "text": "Spend the morning in Akihabara, Tokyo's anime, manga, and gaming hub. Visit multi-story anime shops (Animate, Mandarake), gaming arcades, and character goods stores. Budget time for arcade games."
        },
        {
          "id": "d4_lunch_title",
          "component": "Text",
          "text": "Lunch (12:30 PM - 1:30 PM)",
          "variant": "h4"
        },
        {
          "id": "d4_lunch_text",
          "component": "Text",
          "text": "Eat at casual ramen shops, conveyor-belt sushi, or themed cafes in Akihabara."
        },
        {
          "id": "d4_afternoon_title",
          "component": "Text",
          "text": "Afternoon (2:00 PM - 5:00 PM)",
          "variant": "h4"
        },
        {
          "id": "d4_afternoon_text",
          "component": "Text",
          "text": "Travel to Shinjuku. Visit the Imperial Palace East Garden or take a leisurely walk through Shinjuku's parks. Alternatively, explore Shinjuku's shopping districts."
        },
        {
          "id": "d4_evening_title",
          "component": "Text",
          "text": "Evening (5:30 PM - 8:30 PM)",
          "variant": "h4"
        },
        {
          "id": "d4_evening_text",
          "component": "Text",
          "text": "Enjoy dinner in Shinjuku. The district has numerous family-friendly restaurants ranging from casual to mid-range."
        },
        {
          "id": "d4_divider",
          "component": "Divider"
        },
        {
          "id": "d4_stats",
          "component": "Text",
          "text": "Estimated Cost: USD 280-350 | Neighborhood: Akihabara, Shinjuku",
          "variant": "caption"
        },
        {
