            "d5_afternoon_text",
            "d5_evening_title",
            "d5_evening_text",
            "d5_divider",
            "d5_stats"
          ]
        },
        {
          "id": "d5_header",
          "component": "Text",
          "text": "Fish Market & Cultural Sites (Tsukiji, Imperial Palace)",
          "variant": "h3"
        },
        {
          "id": "d5_morning_title",
          "component": "Text",
          "text": "Morning (7:00 AM - 11:00 AM)",
          "variant": "h4"
        },
        {
          "id": "d5_morning_text",
          "component": "Text",
          "text": "Rise early to visit Tsukiji Outer Market. Experience the bustling fish market, sample fresh sushi breakfast at Sushizanmai or market stalls, and browse food and cookware shops."
        },
        {
          "id": "d5_afternoon_title",
          "component": "Text",
          "text": "Late Morning/Afternoon (11:30 AM - 4:00 PM)",
          "variant": "h4"
        },
        {
          "id": "d5_afternoon_text",
          "component": "Text",
          "text": "Visit the Imperial Palace East Garden, which offers peaceful walks and traditional architecture. Alternatively, visit the Edo-Tokyo Museum for interactive history exhibits."
        },
        {
          "id": "d5_evening_title",
          "component": "Text",
          "text": "Evening (6:30 PM onwards)",
          "variant": "h4"
        },
        {
          "id": "d5_evening_text",
          "component": "Text",
          "text": "Dinner near your hotel or at a favorite restaurant from earlier in the trip. Prepare for departure."
        },
